import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find strongly associated features (p < 0.05 and |t| > 2)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (feats.x[:, i].std() + 1e-8)
            if abs(t_stat) > 2 and feats.y.mean() > 0.1:  # basic signal check
                strong_features.append(fid)

    # Check for correlated pairs with high correlation (|r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j: continue
            if feats.types[i] != 'derived' and feats.types[j] != 'derived':
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) >= 0.6:
                    correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Select top features by t-statistic
    t_stats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (feats.x[:, i].std() + 1e-8)
            t_stats.append((abs(t), fid))
    t_stats.sort(reverse=True)
    top_features = [fid for _, fid in t_stats[:10]]

    # Look for product terms between top features
    products = []
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features):
            if i >= j: continue
            if (fid1, fid2) not in correlated_pairs and (fid2, fid1) not in correlated_pairs:
                products.append((fid1, fid2))

    # Return best product term found, otherwise empty design
    if len(products) > 0:
        return Design(
            drivers=(products[0][0], products[0][1]),
            columns=products[0],
            products=products[:1],
            loadings={}
        )
    else:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

